[{"type":"text","text":"===== ORIGINAL contractDialog.vue (HEAD) =====
<template>
  <zs-dialog title="选择合同版本" v-bind="$attrs" @close="close" v-on="$listeners">
    <div class="dialog-right">
      <keyword-search @search="handleSearch" @submit.native.prevent />
      <zs-table ref="table" :data="tableData" row-key="versionNo">
        <zs-table-column type="index" label="序号" width="60" />
        <zs-table-column label="合同版本编号" prop="versionNo" />
        <zs-table-column label="合同版本名称" prop="versionName" :index="set" />
      </zs-table>
      <zs-pagination v-show="page.total > 0" :total="page.total" :page.sync="page.pageNum" :limit.sync="page.pageSize" @pagination="changePage" />
    </div>
  </zs-dialog>
</template>
<script>
import { listVersionManagement } from '@/views/contract/utils/contractRequest'
import keywordSearch from '@/views/commercialHousingSales/presale/template/components/keywordSearch'
export default {
  name: 'ContractDialog',
  components: { keywordSearch },
  data() {
    return {
      page: {
        pageSize: 10,
        pageNum: 1,
        total: 4
      },
      tableData: []
    }
  },
  created() {
    this.getContractVersionList(1)
  },
  methods: {
    /**
     * 获取合同表格数据
     * @param pageNum
     */
    getContractVersionList(pageNum, keyWord) {
      this.page.pageNum = pageNum || this.page.pageNum
      listVersionManagement({
        pageNum: this.page.pageNum,
        pageSize: this.page.pageSize,
        bizState: '2',
        keyWord
      }).then((response) => {
        this.tableData = response.rows
        this.page.total = response.total
      })
    },
    set(row) {
      this.$emit('set', row)
      this.close()
    },
    close() {
      this.$emit('update:visible', false)
      this.$refs.table?.clearSelection()
    },
    changePage() {
      this.getContractVersionList()
    },
    handleSearch(keyword) {
      this.getContractVersionList(1, keyword)
    }
  }
}
</script>
<style  scoped>
.pagination-container {
  margin-bottom: 20px;
}
</style>
"}]

