tool_input.new_string:
handleSetData(row) {
  // 透传选中行给父组件（保持原 @set 契约不变），并关闭弹窗
  // 原 hand-rolled 弹窗在选中后自行 close；公共 SelectDialog 的确认仅 emit setData，
  // 而父组件的 setContractData 不负责关窗，故此处补上 update:visible 关闭弹窗。
  this.$emit('set', row)
  this.$emit('update:visible', false)
}

